contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes callee and calldata and an amount to attempt sending (though C.forward does not accept value)
    function run(address callee, bytes calldata data, uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // record balances before
        uint256 beforeTestBal = address(this).balance;
        uint256 beforeCbal = address(c).balance;

        bool reverted;
        // call forward; it does not accept value, but we still attempt to call without value
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record balances after
        uint256 afterTestBal = address(this).balance;
        uint256 afterCbal = address(c).balance;

        // General rule asserted: either the call reverted, or it succeeded and neither the test contract's balance
        // nor the contract C's balance decreased, i.e., balances unchanged when forward returns successfully.
        assert(reverted || (afterTestBal == beforeTestBal && afterCbal >= beforeCbal));
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

