// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(address callee, bytes memory data, uint256 sendAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeTestBal = address(this).balance;
        uint256 beforeCbal = address(c).balance;
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTestBal = address(this).balance;
        uint256 afterCbal = address(c).balance;
        assertTrue(reverted || (afterTestBal == beforeTestBal && afterCbal >= beforeCbal));
    }

    function testFuzz_run(address callee, bytes memory data, uint256 sendAmount) public {
        vm.assume(callee.code.length == 0 && uint160(callee) > 0xffff && callee != address(this) && callee != address(c) && callee != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && callee != 0x000000000000000000636F6e736F6c652e6c6f67 && callee != 0x4e59b44847b379578588920cA78FbF26c0B4956C && callee != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(callee, data, sendAmount);
    }

    receive() external payable {}
}
